using System;
using System.Data;
using GymAndFitnessManagementSystem.Common;
namespace GymAndFitnessManagementSystem.Data
{
    public static class Repositories
    {
        public static DataRow Login(string id, string password)
        {
            var t=Db.Query(@"SELECT u.UserId,u.FullName,u.Email,u.UserType,u.Status,g.GymId FROM Users u LEFT JOIN Gyms g ON g.OwnerUserId=u.UserId WHERE (u.Email=@id OR CAST(u.UserId AS varchar(20))=@id) AND u.PasswordHash=@pw AND u.Status='Active'", Db.P("@id",id), Db.P("@pw",PasswordHasher.Hash(password)));
            return t.Rows.Count==0?null:t.Rows[0];
        }
        public static void RegisterCustomer(string name,string email,string password,string phone,string address)
        {
            Db.Execute(@"INSERT INTO Users(FullName,Email,PasswordHash,Phone,Address,UserType,Status) VALUES(@n,@e,@p,@ph,@a,'Customer','Active')",Db.P("@n",name),Db.P("@e",email),Db.P("@p",PasswordHasher.Hash(password)),Db.P("@ph",phone),Db.P("@a",address));
        }
        public static DataTable PendingAndActiveGyms()=>Db.Query(@"SELECT g.GymId,g.GymName,u.FullName Owner,u.Email,g.Address,g.Status,g.CommissionRate FROM Gyms g JOIN Users u ON u.UserId=g.OwnerUserId ORDER BY CASE g.Status WHEN 'Pending' THEN 0 ELSE 1 END,g.GymName");
        public static void SetGymStatus(int gymId,string status){ Db.Execute("UPDATE Gyms SET Status=@s WHERE GymId=@g; UPDATE Users SET Status=CASE WHEN @s='Suspended' THEN 'Suspended' ELSE 'Active' END WHERE UserId=(SELECT OwnerUserId FROM Gyms WHERE GymId=@g)",Db.P("@s",status),Db.P("@g",gymId)); }
        public static DataTable Categories()=>Db.Query("SELECT CategoryId,CategoryName,Description FROM Categories ORDER BY CategoryName");
        public static void AddCategory(string n,string d)=>Db.Execute("INSERT INTO Categories(CategoryName,Description) VALUES(@n,@d)",Db.P("@n",n),Db.P("@d",d));
        public static void DeleteCategory(int id)=>Db.Execute("DELETE FROM Categories WHERE CategoryId=@id",Db.P("@id",id));
        public static DataTable PlatformSummary()=>Db.Query(@"SELECT COUNT(DISTINCT o.OrderId) Orders,ISNULL(SUM(o.TotalAmount),0) GrossSales,ISNULL(SUM(o.PlatformCommission),0) Commission,COUNT(DISTINCT oi.GymId) SellingGyms FROM Orders o LEFT JOIN OrderItems oi ON oi.OrderId=o.OrderId WHERE o.PaymentStatus='Paid'");
        public static DataTable LowRatedGyms()=>Db.Query(@"SELECT g.GymId,g.GymName,CAST(AVG(CAST(r.Rating AS decimal(5,2))) AS decimal(5,2)) AvgRating,COUNT(r.ReviewId) Reviews FROM Gyms g JOIN Items i ON i.GymId=g.GymId JOIN Reviews r ON r.ItemId=i.ItemId AND r.IsVisible=1 GROUP BY g.GymId,g.GymName HAVING AVG(CAST(r.Rating AS decimal(5,2)))<3.5 ORDER BY AvgRating");
        public static DataTable GymProfile(int gymId)=>Db.Query("SELECT GymId,GymName,Address,Contact,LogoPath,Status,CommissionRate FROM Gyms WHERE GymId=@g",Db.P("@g",gymId));
        public static void UpdateGym(int gymId,string name,string address,string contact)=>Db.Execute("UPDATE Gyms SET GymName=@n,Address=@a,Contact=@c WHERE GymId=@g",Db.P("@n",name),Db.P("@a",address),Db.P("@c",contact),Db.P("@g",gymId));
        public static DataTable ItemsForGym(int gymId)=>Db.Query(@"SELECT i.ItemId,i.ItemName,i.ItemType,c.CategoryName,i.Price,i.StockQty,i.MinStock,i.IsAvailable,i.Description FROM Items i JOIN Categories c ON c.CategoryId=i.CategoryId WHERE i.GymId=@g ORDER BY i.ItemId DESC",Db.P("@g",gymId));
        public static void AddItem(int gymId,int cat,string name,string type,decimal price,int stock,int min,string desc)=>Db.Execute(@"INSERT INTO Items(GymId,CategoryId,ItemName,ItemType,Price,StockQty,MinStock,Description,IsAvailable) VALUES(@g,@c,@n,@t,@p,@s,@m,@d,1)",Db.P("@g",gymId),Db.P("@c",cat),Db.P("@n",name),Db.P("@t",type),Db.P("@p",price),Db.P("@s",stock),Db.P("@m",min),Db.P("@d",desc));
        public static void UpdateItem(int id,int cat,string name,string type,decimal price,int stock,int min,string desc)=>Db.Execute(@"UPDATE Items SET CategoryId=@c,ItemName=@n,ItemType=@t,Price=@p,StockQty=@s,MinStock=@m,Description=@d WHERE ItemId=@id",Db.P("@c",cat),Db.P("@n",name),Db.P("@t",type),Db.P("@p",price),Db.P("@s",stock),Db.P("@m",min),Db.P("@d",desc),Db.P("@id",id));
        public static void DeleteItem(int id)=>Db.Execute("DELETE FROM Items WHERE ItemId=@id",Db.P("@id",id));
        public static DataTable Trainers(int gymId)=>Db.Query("SELECT TrainerId,TrainerName,Specialization,Phone,ExperienceYears,Availability FROM Trainers WHERE GymId=@g ORDER BY TrainerName",Db.P("@g",gymId));
        public static void AddTrainer(int gym,string name,string spec,string phone,int exp,string avail)=>Db.Execute("INSERT INTO Trainers(GymId,TrainerName,Specialization,Phone,ExperienceYears,Availability) VALUES(@g,@n,@s,@p,@e,@a)",Db.P("@g",gym),Db.P("@n",name),Db.P("@s",spec),Db.P("@p",phone),Db.P("@e",exp),Db.P("@a",avail));
        public static void DeleteTrainer(int id)=>Db.Execute("DELETE FROM Trainers WHERE TrainerId=@id",Db.P("@id",id));
        public static DataTable LowStock(int gymId)=>Db.Query("SELECT ItemId,ItemName,ItemType,StockQty,MinStock FROM Items WHERE GymId=@g AND ItemType='Product' AND StockQty<=MinStock ORDER BY StockQty",Db.P("@g",gymId));
        public static DataTable GymSales(int gymId)=>Db.Query(@"SELECT o.OrderId,o.OrderDate,u.FullName Customer,i.ItemName,oi.Quantity,oi.UnitPrice,oi.Subtotal FROM OrderItems oi JOIN Orders o ON o.OrderId=oi.OrderId JOIN Users u ON u.UserId=o.CustomerUserId JOIN Items i ON i.ItemId=oi.ItemId WHERE oi.GymId=@g AND o.PaymentStatus='Paid' ORDER BY o.OrderDate DESC",Db.P("@g",gymId));
        public static decimal GymEarnings(int gymId){ var x=Db.Scalar(@"SELECT ISNULL(SUM(oi.Subtotal*(1-g.CommissionRate)),0) FROM OrderItems oi JOIN Orders o ON o.OrderId=oi.OrderId JOIN Gyms g ON g.GymId=oi.GymId WHERE oi.GymId=@g AND o.PaymentStatus='Paid'",Db.P("@g",gymId)); return Convert.ToDecimal(x); }
        public static DataTable Offers(int gymId)=>Db.Query(@"SELECT o.OfferId,i.ItemName,o.DiscountPercent,o.StartDate,o.EndDate,o.IsActive FROM Offers o JOIN Items i ON i.ItemId=o.ItemId WHERE i.GymId=@g ORDER BY o.EndDate DESC",Db.P("@g",gymId));
        public static void AddOffer(int itemId,decimal pct,DateTime start,DateTime end)=>Db.Execute("INSERT INTO Offers(ItemId,DiscountPercent,StartDate,EndDate,IsActive) VALUES(@i,@p,@s,@e,1)",Db.P("@i",itemId),Db.P("@p",pct),Db.P("@s",start),Db.P("@e",end));
        public static void DeleteOffer(int offerId)=>Db.Execute("DELETE FROM Offers WHERE OfferId=@i",Db.P("@i",offerId));
        public static DataTable GymReviews(int gymId)=>Db.Query(@"SELECT r.ReviewId,u.FullName Customer,i.ItemName,r.Rating,r.Comment,r.ReviewDate,r.IsVisible FROM Reviews r JOIN Users u ON u.UserId=r.CustomerUserId JOIN Items i ON i.ItemId=r.ItemId WHERE i.GymId=@g ORDER BY r.ReviewDate DESC",Db.P("@g",gymId));
        public static DataTable Browse(string search,int? category,string type,string priceRange,string location)
        {
            decimal? min=null,max=null; if(priceRange=="Under 1000") max=1000; else if(priceRange=="1000 - 3000"){min=1000;max=3000;} else if(priceRange=="3000+") min=3000;
            return Db.Query(@"SELECT i.ItemId,g.GymName,i.ItemName,i.ItemType,c.CategoryName,i.Price,i.StockQty,g.Address,CAST(ISNULL(AVG(CAST(r.Rating AS decimal(5,2))),0) AS decimal(5,2)) Rating,CAST(ISNULL(MAX(CASE WHEN o.IsActive=1 AND GETDATE() BETWEEN o.StartDate AND o.EndDate THEN o.DiscountPercent ELSE 0 END),0) AS decimal(5,2)) Discount FROM Items i JOIN Gyms g ON g.GymId=i.GymId AND g.Status='Active' JOIN Categories c ON c.CategoryId=i.CategoryId LEFT JOIN Reviews r ON r.ItemId=i.ItemId AND r.IsVisible=1 LEFT JOIN Offers o ON o.ItemId=i.ItemId WHERE i.IsAvailable=1 AND (@q='' OR i.ItemName LIKE '%'+@q+'%' OR g.GymName LIKE '%'+@q+'%' OR i.Description LIKE '%'+@q+'%') AND (@cat IS NULL OR i.CategoryId=@cat) AND (@type='' OR i.ItemType=@type) AND (@min IS NULL OR i.Price>=@min) AND (@max IS NULL OR i.Price<=@max) AND (@loc='' OR g.Address LIKE '%'+@loc+'%') GROUP BY i.ItemId,g.GymName,i.ItemName,i.ItemType,c.CategoryName,i.Price,i.StockQty,g.Address ORDER BY i.ItemName",Db.P("@q",search??""),Db.P("@cat",category),Db.P("@type",type??""),Db.P("@min",min),Db.P("@max",max),Db.P("@loc",location??""));
        }
        public static DataTable ItemDetails(int itemId)=>Db.Query(@"SELECT i.ItemId,g.GymName,i.ItemName,i.ItemType,c.CategoryName,i.Price,i.StockQty,i.Description,g.Address,CAST(ISNULL(MAX(CASE WHEN o.IsActive=1 AND GETDATE() BETWEEN o.StartDate AND o.EndDate THEN o.DiscountPercent ELSE 0 END),0) AS decimal(5,2)) Discount FROM Items i JOIN Gyms g ON g.GymId=i.GymId JOIN Categories c ON c.CategoryId=i.CategoryId LEFT JOIN Offers o ON o.ItemId=i.ItemId WHERE i.ItemId=@i GROUP BY i.ItemId,g.GymName,i.ItemName,i.ItemType,c.CategoryName,i.Price,i.StockQty,i.Description,g.Address",Db.P("@i",itemId));
        public static DataTable ItemReviews(int itemId)=>Db.Query(@"SELECT u.FullName Customer,r.Rating,r.Comment,r.ReviewDate FROM Reviews r JOIN Users u ON u.UserId=r.CustomerUserId WHERE r.ItemId=@i AND r.IsVisible=1 ORDER BY r.ReviewDate DESC",Db.P("@i",itemId));
        private static int GetOrCreateCart(int customer){ var x=Db.Scalar("SELECT CartId FROM Carts WHERE CustomerUserId=@u",Db.P("@u",customer)); if(x!=null&&x!=DBNull.Value)return Convert.ToInt32(x); return Convert.ToInt32(Db.Scalar("INSERT INTO Carts(CustomerUserId,UpdatedAt) OUTPUT INSERTED.CartId VALUES(@u,GETDATE())",Db.P("@u",customer))); }
        public static void AddToCart(int customer,int item,int qty){ int cart=GetOrCreateCart(customer); Db.Execute(@"IF EXISTS(SELECT 1 FROM CartItems WHERE CartId=@c AND ItemId=@i) UPDATE CartItems SET Quantity=Quantity+@q WHERE CartId=@c AND ItemId=@i ELSE INSERT INTO CartItems(CartId,ItemId,Quantity) VALUES(@c,@i,@q); UPDATE Carts SET UpdatedAt=GETDATE() WHERE CartId=@c",Db.P("@c",cart),Db.P("@i",item),Db.P("@q",qty)); }
        public static DataTable Cart(int customer)=>Db.Query(@"SELECT ci.CartItemId,i.ItemId,g.GymName,i.ItemName,ci.Quantity,i.Price,CAST(ISNULL(MAX(CASE WHEN o.IsActive=1 AND GETDATE() BETWEEN o.StartDate AND o.EndDate THEN o.DiscountPercent ELSE 0 END),0) AS decimal(5,2)) Discount,CAST(ci.Quantity*i.Price*(1-ISNULL(MAX(CASE WHEN o.IsActive=1 AND GETDATE() BETWEEN o.StartDate AND o.EndDate THEN o.DiscountPercent ELSE 0 END),0)/100.0) AS decimal(10,2)) LineTotal FROM Carts c JOIN CartItems ci ON ci.CartId=c.CartId JOIN Items i ON i.ItemId=ci.ItemId JOIN Gyms g ON g.GymId=i.GymId LEFT JOIN Offers o ON o.ItemId=i.ItemId WHERE c.CustomerUserId=@u GROUP BY ci.CartItemId,i.ItemId,g.GymName,i.ItemName,ci.Quantity,i.Price",Db.P("@u",customer));
        public static void RemoveCartItem(int id)=>Db.Execute("DELETE FROM CartItems WHERE CartItemId=@i",Db.P("@i",id));
        public static int Checkout(int customer,string paymentMethod)
        {
            using(var c=Db.Open()) using(var tx=c.BeginTransaction())
            {
                try
                {
                    var get=new System.Data.SqlClient.SqlCommand(@"SELECT ci.ItemId,ci.Quantity,i.GymId,i.Price,i.StockQty,i.ItemType,ISNULL(MAX(CASE WHEN o.IsActive=1 AND GETDATE() BETWEEN o.StartDate AND o.EndDate THEN o.DiscountPercent ELSE 0 END),0) Discount,g.CommissionRate FROM Carts ca JOIN CartItems ci ON ci.CartId=ca.CartId JOIN Items i ON i.ItemId=ci.ItemId JOIN Gyms g ON g.GymId=i.GymId LEFT JOIN Offers o ON o.ItemId=i.ItemId WHERE ca.CustomerUserId=@u GROUP BY ci.ItemId,ci.Quantity,i.GymId,i.Price,i.StockQty,i.ItemType,g.CommissionRate",c,tx); get.Parameters.AddWithValue("@u",customer); var dt=new DataTable(); new System.Data.SqlClient.SqlDataAdapter(get).Fill(dt); if(dt.Rows.Count==0) throw new Exception("Cart is empty.");
                    decimal total=0,commission=0; foreach(DataRow r in dt.Rows){ int q=Convert.ToInt32(r["Quantity"]); if(r["ItemType"].ToString()=="Product" && Convert.ToInt32(r["StockQty"])<q) throw new Exception("Not enough stock for one or more products."); decimal price=Convert.ToDecimal(r["Price"]),disc=Convert.ToDecimal(r["Discount"]),line=q*price*(1-disc/100m); total+=line; commission+=line*Convert.ToDecimal(r["CommissionRate"]); }
                    var orderCmd=new System.Data.SqlClient.SqlCommand(@"INSERT INTO Orders(CustomerUserId,OrderDate,TotalAmount,PlatformCommission,PaymentMethod,PaymentStatus,OrderStatus) OUTPUT INSERTED.OrderId VALUES(@u,GETDATE(),@t,@c,@m,'Paid','Confirmed')",c,tx); orderCmd.Parameters.AddWithValue("@u",customer);orderCmd.Parameters.AddWithValue("@t",total);orderCmd.Parameters.AddWithValue("@c",commission);orderCmd.Parameters.AddWithValue("@m",paymentMethod); int order=Convert.ToInt32(orderCmd.ExecuteScalar());
                    foreach(DataRow r in dt.Rows){ int item=Convert.ToInt32(r["ItemId"]),q=Convert.ToInt32(r["Quantity"]),gym=Convert.ToInt32(r["GymId"]); decimal price=Convert.ToDecimal(r["Price"]),disc=Convert.ToDecimal(r["Discount"]),discountAmount=q*price*(disc/100m),sub=q*price-discountAmount; var oi=new System.Data.SqlClient.SqlCommand("INSERT INTO OrderItems(OrderId,ItemId,GymId,Quantity,UnitPrice,DiscountAmount,Subtotal) VALUES(@o,@i,@g,@q,@p,@d,@s)",c,tx); oi.Parameters.AddWithValue("@o",order);oi.Parameters.AddWithValue("@i",item);oi.Parameters.AddWithValue("@g",gym);oi.Parameters.AddWithValue("@q",q);oi.Parameters.AddWithValue("@p",price);oi.Parameters.AddWithValue("@d",discountAmount);oi.Parameters.AddWithValue("@s",sub);oi.ExecuteNonQuery(); if(r["ItemType"].ToString()=="Product"){var st=new System.Data.SqlClient.SqlCommand("UPDATE Items SET StockQty=StockQty-@q WHERE ItemId=@i",c,tx);st.Parameters.AddWithValue("@q",q);st.Parameters.AddWithValue("@i",item);st.ExecuteNonQuery();} }
                    var pay=new System.Data.SqlClient.SqlCommand("INSERT INTO Payments(OrderId,Amount,Method,ReferenceNo,PaidAt,Status) VALUES(@o,@a,@m,@r,GETDATE(),'Paid')",c,tx);pay.Parameters.AddWithValue("@o",order);pay.Parameters.AddWithValue("@a",total);pay.Parameters.AddWithValue("@m",paymentMethod);pay.Parameters.AddWithValue("@r","GFMS-"+DateTime.Now.ToString("yyyyMMddHHmmss"));pay.ExecuteNonQuery();
                    var clear=new System.Data.SqlClient.SqlCommand("DELETE ci FROM CartItems ci JOIN Carts ca ON ca.CartId=ci.CartId WHERE ca.CustomerUserId=@u",c,tx);clear.Parameters.AddWithValue("@u",customer);clear.ExecuteNonQuery(); tx.Commit(); return order;
                }catch{tx.Rollback();throw;}
            }
        }
        public static DataTable Orders(int customer)=>Db.Query("SELECT OrderId,OrderDate,TotalAmount,PaymentMethod,PaymentStatus,OrderStatus FROM Orders WHERE CustomerUserId=@u ORDER BY OrderDate DESC",Db.P("@u",customer));
        public static DataTable OrderItems(int order)=>Db.Query(@"SELECT i.ItemName,g.GymName,oi.Quantity,oi.UnitPrice,oi.DiscountAmount,oi.Subtotal FROM OrderItems oi JOIN Items i ON i.ItemId=oi.ItemId JOIN Gyms g ON g.GymId=oi.GymId WHERE oi.OrderId=@o",Db.P("@o",order));
        public static void AddReview(int customer,int item,int rating,string comment)=>Db.Execute(@"IF EXISTS(SELECT 1 FROM Reviews WHERE CustomerUserId=@u AND ItemId=@i) UPDATE Reviews SET Rating=@r,Comment=@c,ReviewDate=GETDATE(),IsVisible=1 WHERE CustomerUserId=@u AND ItemId=@i ELSE INSERT INTO Reviews(CustomerUserId,ItemId,Rating,Comment,ReviewDate,IsVisible) VALUES(@u,@i,@r,@c,GETDATE(),1)",Db.P("@u",customer),Db.P("@i",item),Db.P("@r",rating),Db.P("@c",comment));
        public static DataTable Profile(int user)=>Db.Query("SELECT UserId,FullName,Email,Phone,Address,UserType,Status FROM Users WHERE UserId=@u",Db.P("@u",user));
        public static void UpdateProfile(int user,string name,string phone,string address,string password){ if(string.IsNullOrWhiteSpace(password)) Db.Execute("UPDATE Users SET FullName=@n,Phone=@p,Address=@a WHERE UserId=@u",Db.P("@n",name),Db.P("@p",phone),Db.P("@a",address),Db.P("@u",user)); else Db.Execute("UPDATE Users SET FullName=@n,Phone=@p,Address=@a,PasswordHash=@pw WHERE UserId=@u",Db.P("@n",name),Db.P("@p",phone),Db.P("@a",address),Db.P("@pw",PasswordHasher.Hash(password)),Db.P("@u",user)); }
        public static void HideReview(int review)=>Db.Execute("UPDATE Reviews SET IsVisible=0 WHERE ReviewId=@r",Db.P("@r",review));
        public static DataTable AllReviews()=>Db.Query(@"SELECT r.ReviewId,u.FullName Customer,g.GymName,i.ItemName,r.Rating,r.Comment,r.ReviewDate,r.IsVisible FROM Reviews r JOIN Users u ON u.UserId=r.CustomerUserId JOIN Items i ON i.ItemId=r.ItemId JOIN Gyms g ON g.GymId=i.GymId ORDER BY r.ReviewDate DESC");
    }
}
